function validate([nums, limit, goal]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 1000000) return 'limit is between 1 and 10^6.';
  if (nums.some(v => !Number.isInteger(v) || Math.abs(v) > limit)) return 'Every value of nums is an integer between -limit and limit.';
  if (!Number.isInteger(goal) || goal < -1000000000 || goal > 1000000000) return 'goal is between -10^9 and 10^9.';
  return null;
}

