function minElements(nums, limit, goal) {
  // k appended values can change the sum by any integer from -k * limit to k * limit,
  // so binary search the smallest k whose reach covers the distance to goal.
  const total = nums.reduce((a, b) => a + b, 0);
  const need = goal > total ? goal - total : total - goal;
  let low = 0;
  let high = need;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (mid * limit >= need) high = mid;
    else low = mid + 1;
  }
  return low;
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const limit = [1, 7, 1000, 1000000][pick(4)];
    const nums = Array.from({ length: 2000 }, () => pick(2 * limit + 1) - limit);
    const goal = pick(2000000001) - 1000000000;
    return [nums, limit, goal];
  }
  const limit = 1 + pick(10);
  const nums = Array.from({ length: 1 + pick(6) }, () => pick(2 * limit + 1) - limit);
  const sum = nums.reduce((a, b) => a + b, 0);
  // Sometimes aim exactly at the current sum or one full step away, otherwise anywhere nearby.
  const roll = rand();
  const goal = roll < 0.15 ? sum : roll < 0.3 ? sum + (rand() < 0.5 ? limit : -limit) : pick(121) - 60;
  return [nums, limit, goal];
}
